const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const headers = (item.json && item.json.headers) || {};
const ts = headers['x-lit-timestamp'];
const eventId = headers['x-lit-event-id'];
const signature = headers['x-lit-signature'];
if (!ts || !eventId || !signature) { throw new Error('Missing signing headers'); }
const body = (item.json && item.json.body) !== undefined ? item.json.body : {};
const rawBody = typeof body === 'string' ? body : JSON.stringify(body);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
const expected = 'v1=' + mac;
const a = Buffer.from(expected);
const b = Buffer.from(String(signature));
const matches = a.length === b.length && crypto.timingSafeEqual(a, b);
if (!matches) { throw new Error('Signature verification failed'); }
const nowSec = Math.floor(Date.now() / 1000);
if (Math.abs(nowSec - Number(ts)) > 300) { throw new Error('Signature timestamp outside tolerance'); }
return [{ json: { verified: true, eventId, timestamp: ts, body } }];

const item = $input.first().json;
const payload = (item.body && item.body.payload) ? item.body.payload : (item.body || {});
const projectId = String(payload.projectId || payload.id || 'prj_' + Date.now()).trim();
const clientName = String(payload.clientName || payload.client || 'Client').trim();
const projectType = String(payload.projectType || 'CUSTOM_SOFTWARE').toUpperCase();
const slug = (payload.repoSlug || projectId.toLowerCase().replace(/[^a-z0-9_-]/g, '-'));
const repoName = `lit-${slug}`;

let templateRepo = 'template-fullstack-nextjs';
if (projectType === 'APP_DEVELOPMENT') templateRepo = 'template-mobile-flutter';
else if (projectType === 'GAME_DEVELOPMENT') templateRepo = 'template-game-unity';
else if (projectType === 'AI_AUTOMATION') templateRepo = 'template-ai-agent-fastapi';
else if (projectType === 'SAAS_DEVELOPMENT') templateRepo = 'template-saas-multitenant';

const githubRepo = {
  owner: 'vikashsaravanann',
  name: repoName,
  fullName: `vikashsaravanann/${repoName}`,
  private: true,
  defaultBranch: 'main',
  templateUsed: templateRepo,
  gitSshUrl: `git@github.com:vikashsaravanann/${repoName}.git`,
  htmlUrl: `github.com/vikashsaravanann/${repoName}`,
  ciWorkflowConfigured: true,
  branchProtection: {
    enforcePrReviews: true,
    requiredReviewers: 1,
    requiredStatusChecks: ['lint', 'typecheck', 'test']
  },
  createdAt: new Date().toISOString()
};

return [{
  json: {
    eventId: item.eventId,
    verified: item.verified,
    projectId,
    clientName,
    projectType,
    githubRepo
  }
}];

const item = $input.first().json;
